import {jest} from '@jest/globals';
import {ToolRegistry} from './registry.js';
import type {ToolExecutor} from './registry.js';

describe('ToolRegistry', () => {
  let registry: ToolRegistry;

  beforeEach(() => {
    registry = new ToolRegistry();
  });

  describe('register', () => {
    it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
      const invalidSchema = {
        type: 'object',
        properties: {
          foo: {type: 'invalid-type'},
        },
      };

      expect(() => {
        registry.register(
          {
            name: 'bad-tool',
            description: 'A tool with a bad schema',
            inputSchema: invalidSchema as unknown as Record<string, unknown>,
          },
          async () => ''
        );
      }).toThrow(/bad-tool/);
    });
  });

  describe('execute', () => {
    it('validates input against the resolved definition inputSchema and returns a ToolResponse on failure', async () => {
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      const response = await registry.execute('weather', {});

      expect(response.result).toMatch(/required.*location/i);
    });

    it('never calls the executor when input fails validation', async () => {
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(
        {
          name: 'weather',
          description: 'Get weather',
          inputSchema: {
            type: 'object',
            properties: {
              location: {type: 'string'},
            },
            required: ['location'],
          },
        },
        execute
      );

      await registry.execute('weather', {});

      expect(execute).not.toHaveBeenCalled();
    });

    it('rejects a wrong-typed field naming the path and type', async () => {
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(
        {
          name: 'type_check',
          description: 'Check types',
          inputSchema: {
            type: 'object',
            properties: {
              val: {type: 'string'},
            },
          },
        },
        execute
      );

      const response = await registry.execute('type_check', {val: 123});

      expect(response.result).toMatch(/val.*string/);
    });

    it('does not echo the offending value in the rejection message', async () => {
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(
        {
          name: 'type_check',
          description: 'Check types',
          inputSchema: {
            type: 'object',
            properties: {
              val: {type: 'string'},
            },
          },
        },
        execute
      );

      const response = await registry.execute('type_check', {val: 123});

      expect(response.result).not.toMatch(/123/);
    });

    it('passes through extra properties to the executor unchanged', async () => {
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(
        {
          name: 'echo',
          description: 'Echo input',
          inputSchema: {
            type: 'object',
            properties: {
              foo: {type: 'string'},
            },
          },
        },
        execute
      );

      const input = {foo: 'bar', extra: 'baz'};
      await registry.execute('echo', input);

      expect(execute).toHaveBeenCalledWith(input, undefined);
    });

    it('throws Unknown tool for an unregistered name', async () => {
      await expect(registry.execute('unknown', {})).rejects.toThrow(/Unknown tool: unknown/);
    });

    it('re-resolves and validates against changing schemas for function-valued sources - first call', async () => {
      let requiredField = 'first';
      const definitionSource = () => ({
        name: 'dynamic',
        description: 'Dynamic schema',
        inputSchema: {
          type: 'object',
          properties: {
            first: {type: 'string'},
            second: {type: 'string'},
          },
          required: [requiredField],
        },
      });

      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(definitionSource, execute);

      const res1 = await registry.execute('dynamic', {second: 'val'});
      expect(res1.result).toMatch(/required.*first/);
    });

    it('re-resolves and validates against changing schemas for function-valued sources - second call', async () => {
      let requiredField = 'second';
      const definitionSource = () => ({
        name: 'dynamic',
        description: 'Dynamic schema',
        inputSchema: {
          type: 'object',
          properties: {
            first: {type: 'string'},
            second: {type: 'string'},
          },
          required: [requiredField],
        },
      });

      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');
      registry.register(definitionSource, execute);

      const res2 = await registry.execute('dynamic', {first: 'val'});
      expect(res2.result).toMatch(/required.*second/);
    });

    it('caches compiled validators for static schemas by reference', async () => {
      const inputSchema = {
        type: 'object',
        properties: {foo: {type: 'string'}},
      };
      const execute = jest.fn<ToolExecutor>().mockResolvedValue('ok');

      registry.register({name: 'static', description: 'desc', inputSchema}, execute);

      for (let i = 0; i < 10; i++) {
        await registry.execute('static', {foo: 'bar'});
      }

      expect(execute).toHaveBeenCalledTimes(10);
    });

    it('does not leak identifying field values in rejection messages', async () => {
      registry.register(
        {
          name: 'secure',
          description: 'Secure tool',
          inputSchema: {
            type: 'object',
            properties: {
              secret: {type: 'string', minLength: 10},
            },
          },
        },
        async () => 'ok'
      );

      const response = await registry.execute('secure', {secret: 'too-short'});

      expect(response.result).not.toMatch(/too-short/);
    });
  });
});

